parameters.jsCode:
// 1. Safely extract data from upstream nodes based on your exact schema
const jdOutputText = $input.first().json.output[0].content[0].text;

// FIXED: Extract the raw resume text string directly from the 'Edit Fields' node
const resumeText = ($('Edit Fields').first().json.resume_text || "").toLowerCase();

let jdData = {};
try {
  // Parse the stringified JSON content coming from the JD Analyzer output
  jdData = JSON.parse(jdOutputText);
} catch (e) {
  // Fallback in case it's already an object
  jdData = jdOutputText;
}

// Extract and combine both skill sets into one comprehensive list
const mustHave = jdData.must_have_skills || [];
const niceToHave = jdData.nice_to_have_skills || [];
const requiredSkills = [...mustHave, ...niceToHave];

// Create a cleanly tokenized array for strict word matching (preserving dots/dashes/slashes)
const cleanResumeTextForWords = resumeText.replace(/[,\(\)\[\]\{\}]/g, " ");
const resumeWords = cleanResumeTextForWords.split(/\s+/);

const matchedSkills = [];
const missingSkills = [];

// 2. Flexible Matching Loop
for (const skill of requiredSkills) {
  const cleanSkill = skill.trim().toLowerCase();
  if (!cleanSkill) continue;

  // Check 1: Direct substring inclusion (perfect for multi-word or special terms like "Node.js", "CI/CD")
  if (resumeText.includes(cleanSkill)) {
    matchedSkills.push(skill);
    continue;
  }

  // Check 2: Word boundary array verification fallback
  if (resumeWords.includes(cleanSkill)) {
    matchedSkills.push(skill);
    continue;
  }

  // Check 3: Stripped boundary check fallback (e.g., matching "CI/CD" if they wrote "CI-CD" or "CI CD")
  const strippedSkill = cleanSkill.replace(/[^a-z0-9]/g, "");
  const strippedResume = resumeText.replace(/[^a-z0-9]/g, "");
  if (strippedSkill && strippedResume.includes(strippedSkill)) {
    matchedSkills.push(skill);
    continue;
  }

  // If all checks fail, the skill is genuinely missing
  missingSkills.push(skill);
}

// 3. Compute mathematical keyword density score
const totalSkills = requiredSkills.length;
const keywordScore = totalSkills > 0 ? Math.round((matchedSkills.length / totalSkills) * 100 * 100) / 100 : 0;

// 4. Return formatted data back to the pipeline
return {
  deterministic_keyword_score: keywordScore,
  matched_skills_count: matchedSkills.length,
  total_required_count: totalSkills,
  verified_matched_skills: matchedSkills,
  verified_missing_skills: missingSkills
};
